// Scratch differential fuzzer: reference executable vs a target command.
//   node fuzz.mjs <count> oracle          -> validate my independent oracle
//   node fuzz.mjs <count> port            -> validate /output/test7.mjs
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test7_executable';
const AL = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const POOLS = [
  " !\"#$%&()*+,-./0123456789:;<=>?@[\\]^_`{|}~'ABCabc\t\n\r",
  '中国汉字日本語한국어',
  'éàüßñ😀🎉👍',
  AL,
  '11zz  ',
  '1',
  AL + '\'"\\ \t',
];

const rs = (n, p) => {
  const cp = [...p];
  let s = '';
  for (let i = 0; i < n; i++) s += cp[Math.floor(Math.random() * cp.length)];
  return s;
};

function run(cmd, pre, argv) {
  try {
    const out = execFileSync(cmd, [...pre, ...argv], {
      encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'], timeout: 30000,
    });
    return { rc: 0, out };
  } catch (e) {
    return { rc: e.status == null ? -1 : e.status, out: e.stdout == null ? '' : e.stdout };
  }
}

const target = Number(process.argv[2] || 300);
const mode = process.argv[3] || 'oracle';
// The oracle takes bare positionals; the port takes real --a/--b flags.
const call = mode === 'oracle'
  ? (a, b) => run(process.execPath, ['/tmp/oracle/oracle.mjs'], [a, b])
  : (a, b) => run(process.execPath, ['/output/test7.mjs'], ['--a', a, '--b', b]);

let n = 0, bad = 0;
for (let i = 0; i < target; i++) {
  const pa = POOLS[Math.floor(Math.random() * POOLS.length)];
  const pb = Math.random() < 0.75 ? AL : POOLS[Math.floor(Math.random() * POOLS.length)];
  const a = rs(Math.floor(Math.random() * 40), pa);
  const b = rs(Math.floor(Math.random() * 30), pb);
  const E = run(EXE, [], ['--a', a, '--b', b]);
  const T = call(a, b);
  n++;
  if (E.rc !== T.rc || E.out !== T.out) {
    bad++;
    console.log('MISMATCH a=', JSON.stringify(a), 'b=', JSON.stringify(b));
    console.log('  exe    rc', E.rc, JSON.stringify(E.out));
    console.log(`  ${mode.padEnd(6)} rc`, T.rc, JSON.stringify(T.out));
    if (bad >= 6) break;
  }
}
console.log(`${mode}-vs-reference: ${n} cases, ${bad} mismatches`);

