// Deterministic acceptance suite: reference executable vs /output/test7.mjs.
// Compares stdout byte-for-byte, exit code, and stderr with only the
// "[PYI-<pid>:ERROR] ..." line normalised away (its number is a pid).
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test7_executable';
const PORT = '/output/test7.mjs';
const AL = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

function run(cmd, pre, argv) {
  const res = { rc: 0, out: '', err: '' };
  try {
    res.out = execFileSync(cmd, [...pre, ...argv], {
      encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 60000,
    });
  } catch (e) {
    res.rc = e.status == null ? -1 : e.status;
    res.out = e.stdout == null ? '' : e.stdout;
    res.err = e.stderr == null ? '' : e.stderr;
  }
  return res;
}
const normErr = (s) => s
  .split('\n')
  .filter((l) => !/^\[PYI-\d+:ERROR\] Failed to execute script 'test7' due to unhandled exception!$/.test(l))
  .join('\n');

// ---- the corpus -----------------------------------------------------------
const C = [];
const add = (...argv) => C.push(argv);

// 1. the four documented sample cases
add('--a', '5aN1QrVUtM5PMaBzNoYFqL5wGSWAw', '--b', '2g');
add('--a', '中国汉字', '--b', 'KAbNUE1LBRuRVeN');
add('--a', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA', '--b', '2NEpo7TZRRrLZSi2U');
add('--a', '5aN1QrVUtM5PMaBzNoYFqL5wGSWAw', '--b', '2722bfR1UtrSp6ixizzEZeVU9B9hBNcHut8QQ2Q');

// 2. empty / trivial
for (const [a, b] of [['', ''], ['x', '2g'], ['', '2g'], ['x', ''], ['a', '1'], ['a', '11']]) add('--a', a, '--b', b);

// 3. leading-'1' -> NUL runs
for (let k = 1; k <= 24; k++) { add('--a', 'z', '--b', '1'.repeat(k)); add('--a', 'z', '--b', '1'.repeat(k) + 'z'); }

// 4. every alphabet char alone, and pairs
for (const ch of AL) add('--a', ch, '--b', ch);
for (const ch of AL) add('--a', 'q', '--b', '2' + ch);

// 5. bytes-repr branches, reached by feeding back the base58 of a chosen string
const REPR_STRINGS = [
  "it's", 'say "hi"', 'both \' and "', '" then \'', "' then \"", 'back\\slash',
  'tab\there', 'nl\nhere', 'cr\rhere', 'bs\\x41', 'bs\\n', 'bs\\t', 'del\x7f',
  '\x01\x02\x03\x1f', '中', 'é', '😀', 'ÿ', '~`!@#$%^&*()_+-=[]{}|;:,.<>/?',
];
// 6. all 256 byte values, alone and in pairs, via a locally computed base58
function b58(bytes) {
  let z = 0; while (z < bytes.length && bytes[z] === 0) z++;
  let acc = 0n; for (const v of bytes.slice(z)) acc = acc * 256n + BigInt(v);
  let s = ''; while (acc > 0n) { s = AL[Number(acc % 58n)] + s; acc /= 58n; }
  return '1'.repeat(z) + s;
}
for (let v = 0; v < 256; v++) {
  add('--a', 'k', '--b', b58([v]));
  add('--a', 'k', '--b', b58([0x41, v, 0x42]));
  add('--a', 'k', '--b', b58([v, 0x27, 0x22]));
  add('--a', 'k', '--b', b58([0x5c, v]));
}

// 7. whitespace / rstrip set
const WS = [0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000, 0x180e, 0x200b, 0xfeff];
for (const cp of WS) {
  const ch = String.fromCodePoint(cp);
  add('--a', 'w', '--b', '2g' + ch);
  add('--a', 'w', '--b', '2g' + ch + ch);
  add('--a', 'w', '--b', ch + '2g');
  add('--a', 'w', '--b', ch);
}

// 8. invalid base58 characters
for (const ch of ['0', 'O', 'I', 'l', '!', '=', '-', '+', '/', '\\', "'", '"', '`', '~', '\t', ' ', '\x7f']) {
  add('--a', 'v', '--b', '2' + ch + 'g');
  add('--a', 'v', '--b', ch);
}

// 9. non-ASCII in --b (ascii-encode failures), incl. position/range reporting
for (const s of ['中', 'é', '😀', 'x中', 'xx中', '中国', '中国汉', 'x中y中', '中x中', 'é中',
  '2g中', '中 ', '中\t', '2g中 ', '2g​', '2g﻿', '\u{10FFFF}', 'a\u{1F600}b']) {
  add('--a', 'n', '--b', s);
}

// 10. UTF-8 encoding of --a
for (const s of ['é', '中国汉字', '😀🎉👍', 'á', 'مرحبا', 'Привет', '�',
  '\u{10FFFF}', 'x'.repeat(200), '中'.repeat(100), AL, AL + AL]) {
  add('--a', s, '--b', '2g');
}
for (const s of REPR_STRINGS) add('--a', s, '--b', '2g');

// 11. argparse shapes
const ARG_SHAPES = [
  [], ['--a', 'x'], ['--b', '2g'], ['--a'], ['--b'], ['-h'], ['--help'], ['--h'], ['--he'], ['--hel'],
  ['--a=x', '--b=2g'], ['--a=', '--b='], ['--a=x', '--b', '2g'], ['--b', '2g', '--a', 'x'],
  ['--a', 'x', '--b', '2g', '--a', 'y'], ['--a=1', '--a=2', '--b', '2g'],
  ['--a', 'x', '--b', '2g', 'extra'], ['--a', 'x', '--b', '2g', 'x', 'y'],
  ['--a', 'x', '--b', '2g', '--zzz'], ['--a', 'x', '--b', '2g', '-z', 'q'],
  ['--a', '--b', '--b', '2g'], ['--a', '-x', '--b', '2g'], ['--a', '-5', '--b', '2g'],
  ['--a', '-1.5', '--b', '2g'], ['--a', '-.5', '--b', '2g'], ['--a', '- 5', '--b', '2g'],
  ['--a', 'x', '--b', '2g', '-1.5'], ['--a', 'x', '--b', '2g', '-.5'],
  ['--a', 'x', '--b', '2g', '- 5'], ['--a', 'x', '--b', '2g', '-5x'],
  ['--a', 'x', '--b', '2g', '-'], ['--a', 'x', '--b', '2g', '--'],
  ['--a', 'x', '--b', '2g', '--', 'extra'], ['--a', 'x', '--', '--b', '2g'],
  ['--', '--a', 'x', '--b', '2g'], ['--a=--b', '--b', '2g'], ['--a', 'x', '--b=2g=z'],
  ['--a=a=b', '--b', '2g'], ['-a', 'x', '--b', '2g'], ['-b', '2g', '--a', 'x'],
  ['--A', 'x', '--b', '2g'], ['--aa', 'x', '--b', '2g'], ['--ab', 'x', '--b', '2g'],
  ['--a', 'x', '-h'], ['-h', '--zzz'], ['--zzz', '-h'], ['--a', '-h'], ['--a', '--help'],
  ['--a', 'x', '-h', '--b'], ['-hx', '--a', 'x', '--b', '2g'], ['--help=x'],
  ['--a', 'x', '--b', '2g', ''], [''], ['--a', 'x', '--b', '2g', '--a'],
  ['--a', 'x', '--b', '2g', '--b'], ['--a', 'x', '--b', '--'], ['--a', '--', '--b', '2g'],
];
for (const s of ARG_SHAPES) C.push(s);

// 12. scale
for (const n of [500, 2000, 6000]) { add('--a', 'A'.repeat(n), '--b', 'z'.repeat(n)); }

// ---- execute --------------------------------------------------------------
let pass = 0; const fails = [];
for (const argv of C) {
  const E = run(EXE, [], argv);
  const T = run(process.execPath, [PORT], argv);
  const ok = E.rc === T.rc && E.out === T.out && normErr(E.err) === normErr(T.err);
  if (ok) { pass++; continue; }
  fails.push({
    argv,
    rc: E.rc === T.rc ? null : [E.rc, T.rc],
    out: E.out === T.out ? null : [E.out, T.out],
    err: normErr(E.err) === normErr(T.err) ? null : [normErr(E.err), normErr(T.err)],
  });
}
console.log(`acceptance: ${pass}/${C.length} identical, ${fails.length} FAIL`);
for (const f of fails.slice(0, 25)) {
  console.log('\nFAIL argv=', JSON.stringify(f.argv));
  if (f.rc) console.log('  rc     exe=%o port=%o', f.rc[0], f.rc[1]);
  if (f.out) console.log('  stdout exe=%s\n         port=%s', JSON.stringify(f.out[0]), JSON.stringify(f.out[1]));
  if (f.err) console.log('  stderr exe=%s\n         port=%s', JSON.stringify(f.err[0]), JSON.stringify(f.err[1]));
}
if (fails.length > 25) console.log(`\n... and ${fails.length - 25} more`);
process.exit(fails.length ? 1 : 0);

